\set ON_ERROR_STOP on
BEGIN;
DO $$ BEGIN IF current_setting('app.disposable_database',true) IS DISTINCT FROM 'YES' THEN RAISE EXCEPTION 'Disposable database only'; END IF; END $$;
CREATE FUNCTION pg_temp.check_rule(ok boolean,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAIL: %',label; END IF; END $$;
INSERT INTO profiles(id,slug,host_public,role_intent,full_name) VALUES ('00000000-0000-0000-0000-000000000001','qa-coach-a',true,'host','QA Coach A'),('00000000-0000-0000-0000-000000000002','qa-coach-b',true,'host','QA Coach B'),('00000000-0000-0000-0000-000000000003','qa-learner',false,'guest','QA Learner');
INSERT INTO auth.users(id,email,email_confirmed_at) VALUES ('00000000-0000-0000-0000-000000000003','qa-learner@example.invalid',now());
INSERT INTO teams(id,owner_id) VALUES ('10000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000001'),('10000000-0000-0000-0000-000000000002','00000000-0000-0000-0000-000000000002');
INSERT INTO offers(id,team_id,host_id,status,kind,title_en) VALUES ('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000001','published','download','QA Resource');
SELECT request_coach_updates('qa-coach-a','pending@example.invalid','en',true,false,true,true,'https://zoheewell.com',false);
SELECT pg_temp.check_rule((SELECT confirmed_at IS NULL AND NOT announcements AND pending_preferences->>'announcements'='true' AND confirmation_hash IS NULL FROM coach_subscriptions WHERE email='pending@example.invalid'),'provider-free pending request never establishes consent');
SELECT pg_temp.check_rule((SELECT count(*)=0 FROM notification_outbox),'no email enqueued without sender');
SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000003',true);
SELECT save_my_coach_updates('qa-coach-a',true,false,true,true);
SELECT save_my_coach_updates('qa-coach-b',false,true,false,true);
SELECT pg_temp.check_rule(my_coach_updates('qa-coach-a')->>'announcements'='true' AND my_coach_updates('qa-coach-b')->>'announcements'='false','verified account preferences are coach-specific');
SELECT save_my_coach_updates('qa-coach-a',false,false,false,true);
SELECT pg_temp.check_rule(my_coach_updates('qa-coach-b')->>'new_events'='true','unsubscribing coach A preserves coach B');
SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
SELECT pg_temp.check_rule(coach_subscriber_segments()->>'confirmed'='0','coach A sees only own aggregates');
SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000002',true);
SELECT pg_temp.check_rule(coach_subscriber_segments()->>'confirmed'='1','coach B aggregate remains intact');
UPDATE coach_subscriptions SET token_hash=encode(extensions.digest(repeat('a',64),'sha256'),'hex'),token_expires_at=now()+interval '7 days' WHERE email='pending@example.invalid';
SELECT pg_temp.check_rule(coach_update_preferences('invalid') IS NULL AND coach_update_preferences(repeat('b',64)) IS NULL,'invalid and forged tokens reveal nothing');
SELECT save_coach_update_preferences(repeat('a',64),true,false,true);
SELECT pg_temp.check_rule(coach_update_preferences(repeat('a',64))->>'announcements'='true','valid token confirms preferences');
SELECT save_coach_update_preferences(repeat('a',64),false,false,false);
SELECT pg_temp.check_rule(coach_update_preferences(repeat('a',64))->>'announcements'='false','token unsubscribe readback');
UPDATE coach_subscriptions SET token_expires_at=now()-interval '1 day' WHERE email='pending@example.invalid';
SELECT pg_temp.check_rule(coach_update_preferences(repeat('a',64)) IS NULL,'expired token denied');
SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
INSERT INTO message_templates(id,team_id,name,channel,language,body) VALUES ('30000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','QA Template','in_app','en','Access {{resource}}');
SELECT save_resource_journey('10000000-0000-0000-0000-000000000001',NULL,'20000000-0000-0000-0000-000000000001','QA Journey','[{"kind":"send","template_id":"30000000-0000-0000-0000-000000000001"}]') AS journey \gset
SELECT pg_temp.check_rule((SELECT name='QA Journey' FROM message_journeys WHERE id=:'journey'),'journey save/readback');
SELECT set_journey_status(:'journey','active');
INSERT INTO entitlements(id,offer_id,user_id,source) VALUES ('40000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000003','free');
SELECT pg_temp.check_rule((SELECT count(*)=1 FROM resource_journey_runs),'enrollment creates exactly one run');
SELECT advance_resource_journeys(50);
SELECT pg_temp.check_rule((SELECT count(*)=1 FROM notifications WHERE body='Access QA Resource' AND link='/offer/20000000-0000-0000-0000-000000000001'),'enrollment delivers real in-app notification');
SELECT advance_resource_journeys(50);
SELECT pg_temp.check_rule((SELECT count(*)=1 FROM notifications),'worker retry does not duplicate notification');
SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000002',true);
DO $$ BEGIN BEGIN PERFORM resource_journey_activity('10000000-0000-0000-0000-000000000001',NULL,20); RAISE EXCEPTION 'cross coach allowed'; EXCEPTION WHEN OTHERS THEN IF SQLERRM<>'forbidden' THEN RAISE; END IF; END; END $$;
SET LOCAL ROLE authenticated;
SELECT pg_temp.check_rule((SELECT count(*)=0 FROM resource_journey_runs),'other coach denied raw run access by RLS');
SELECT pg_temp.check_rule((SELECT count(*)=0 FROM notifications),'other coach denied learner notification access by RLS');
RESET ROLE;
SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000003',true);
SET LOCAL ROLE authenticated;
SELECT pg_temp.check_rule((SELECT count(*)=1 FROM notifications),'learner reads only their delivered notification');
RESET ROLE;
SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
INSERT INTO entitlements(id,offer_id,user_id,source) VALUES ('40000000-0000-0000-0000-000000000002','20000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000003','free');
UPDATE offers SET status='archived' WHERE id='20000000-0000-0000-0000-000000000001';
SELECT advance_resource_journeys(50);
SELECT pg_temp.check_rule((SELECT count(*)=1 FROM notifications),'archive stops pending delivery');
SELECT pg_temp.check_rule((SELECT count(*)=1 FROM resource_journey_runs WHERE note='resource_unavailable'),'archived stop visible in run history');
SELECT pg_temp.check_rule(NOT has_table_privilege('anon','coach_subscriptions','SELECT') AND NOT has_table_privilege('authenticated','coach_subscriptions','SELECT'),'subscriber contacts are service-only');
ROLLBACK;
\echo 'Website Notes disposable database assertions passed; fixtures rolled back.'
